import{_ as o,o as t,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"滚动行为","description":"使用前端路由，当切换到新路由时，想要页面滚到顶部，或者是保持原先的滚动位置，就像重新加载页面那样。 vue router 能做到，而且更好，它让你可以自定义路由切换时页面如何滚动。 注意 : 这个功能只在支持 history.pushState 的浏览器中可用。 当创建一个 Ro。","frontmatter":{"title":"滚动行为","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"使用前端路由，当切换到新路由时，想要页面滚到顶部，或者是保持原先的滚动位置，就像重新加载页面那样。 vue router 能做到，而且更好，它让你可以自定义路由切换时页面如何滚动。 注意 : 这个功能只在支持 history.pushState 的浏览器中可用。 当创建一个 Ro。","sidebarWeight":51,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/滚动行为.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/滚动行为.md","filePath":"posts/Vue系统教程/04-路由与状态管理/滚动行为.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/滚动行为.md"};function i(n,e,u,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="滚动行为" tabindex="-1">滚动行为 <a class="header-anchor" href="#滚动行为" aria-label="Permalink to &quot;滚动行为&quot;">​</a></h1><blockquote><p>本节目标：理解“滚动行为”的核心思路，并能把它用于实际开发或面试表达。 使用前端路由，当切换到新路由时，想要页面滚到顶部，或者是保持原先的滚动位置，就像重新加载页面那样。 vue-router 能做到，而且更好，它让你可以自定义路由切换时页面如何滚动。 <strong>注意</strong>**😗* <strong>这个功能只在支持</strong> <strong>history.pushState</strong> <strong>的浏览器中可用。</strong></p></blockquote><p>当创建一个 Router 实例，你可以提供一个 scrollBehavior 方法： const router = createRouter({ history: createWebHashHistory(), routes: [...], scrollBehavior (to, from, savedPosition) { // return 期望滚动到哪个的位置 } }) scrollBehavior 函数接收 to和 from 路由对象，如 Navigation Guards。第三个参数 savedPosition，只有当这是一个 popstate 导航时才可用（由浏览器的后退/前进按钮触发）。 该函数可以返回一个 ScrollToOptions 位置对象: const router = createRouter({ scrollBehavior(to, from, savedPosition) { // 始终滚动到顶部 return { top: 0 } }, }) 你也可以通过 el 传递一个 CSS 选择器或一个 DOM 元素。在这种情况下，top 和 left 将被视为该元素的相对偏移量。 const router = createRouter({ scrollBehavior(to, from, savedPosition) { // 始终在元素 #main 上方滚动 10px return { // 也可以这么写 // el: document.getElementById(&#39;main&#39;), el: &#39;#main&#39;, top: -10, } }, }) 如果返回一个 falsy 的值，或者是一个空对象，那么不会发生滚动。</p><p>返回 savedPosition，在按下 后退/前进 按钮时，就会像浏览器的原生表现那样： const router = createRouter({ scrollBehavior(to, from, savedPosition) { if (savedPosition) { return savedPosition } else { return { top: 0 } } }, })</p><p>如果你要模拟 “滚动到锚点” 的行为： const router = createRouter({ scrollBehavior(to, from, savedPosition) { if (to.hash) { return { el: to.hash, } } }, })</p><p>如果你的浏览器支持滚动行为，你可以让它变得更流畅： const router = createRouter({ scrollBehavior(to, from, savedPosition) { if (to.hash) { return { el: to.hash, behavior: &#39;smooth&#39;, } } } })</p><p>延迟滚动 有时候，我们需要在页面中滚动之前稍作等待。例如，当处理过渡时，我们希望等待过渡结束后再滚动。要做到这一点，你可以返回一个 Promise，它可以返回所需的位置描述符。下面是一个例子，我们在滚动前等待 500ms： const router = createRouter({ scrollBehavior(to, from, savedPosition) { return new Promise((resolve, reject) =&gt; { setTimeout(() =&gt; { resolve({ left: 0, top: 0 }) }, 500) }) }, }) 我们可以将其与页面级过渡组件的事件挂钩，以使滚动行为与你的页面过渡很好地结合起来，但由于使用场景可能存在的差异和复杂性，我们只是提供了这个基础来实现特定的用户场景。</p></div>',1)])])}const v=o(a,[["render",i]]);export{h as __pageData,v as default};
